/**
 * Demo data adapter — answers the same questions as the backend API, from a static
 * snapshot (`public/demo/snapshot.json`, generated by `scripts/export_demo_snapshot.py`).
 *
 * Owns: snapshot loading/caching and pure query helpers over the snapshot.
 * Does NOT own: HTTP, React state. `client.ts` routes calls here when IS_DEMO_MODE is on.
 *
 * All query helpers are pure (snapshot in → result out) so they are unit-testable.
 */
import type {
  CanvasViewport,
  CausalityLink,
  ConnectedEvent,
  EventDetail,
  HistoricalEvent,
  Perspective,
  SearchResult,
  TileResponse,
} from '../types';
import { demoSnapshotUrl } from '../config/demo';

/** License / attribution block embedded in the snapshot. */
export interface DemoLicense {
  data: string;
  text: string;
  credit: string;
  details: string;
}

/** Shape of `public/demo/snapshot.json`. */
export interface DemoSnapshot {
  version: number;
  generator?: string;
  source?: string;
  license: DemoLicense;
  stats?: Record<string, number>;
  events: HistoricalEvent[];
  links: CausalityLink[];
  /** Per-event extras keyed by slug (perspectives are the bulky part). */
  details: Record<string, { perspectives?: Perspective[] }>;
}

// ─────────────────────────────────────────────────────────────────────────────
// Loading
// ─────────────────────────────────────────────────────────────────────────────

let snapshotPromise: Promise<DemoSnapshot> | null = null;

/** Validate the minimum structure we depend on; throws on malformed data. */
export function parseSnapshot(raw: unknown): DemoSnapshot {
  if (!raw || typeof raw !== 'object') throw new Error('Demo snapshot: not an object');
  const s = raw as Partial<DemoSnapshot>;
  if (!Array.isArray(s.events) || !Array.isArray(s.links)) {
    throw new Error('Demo snapshot: missing events or links');
  }
  return {
    version: typeof s.version === 'number' ? s.version : 1,
    generator: s.generator,
    source: s.source,
    license: s.license ?? { data: '', text: '', credit: '', details: '' },
    stats: s.stats,
    events: s.events,
    links: s.links,
    details: s.details ?? {},
  };
}

/** Fetch the snapshot once per page load (cached; a failed fetch can be retried). */
export function loadDemoSnapshot(fetchImpl: typeof fetch = fetch): Promise<DemoSnapshot> {
  if (!snapshotPromise) {
    snapshotPromise = fetchImpl(demoSnapshotUrl())
      .then((res) => {
        if (!res.ok) throw new Error(`Demo snapshot: HTTP ${res.status}`);
        return res.json();
      })
      .then(parseSnapshot)
      .catch((err) => {
        snapshotPromise = null;
        throw err;
      });
  }
  return snapshotPromise;
}

/** Test helper — clears the cached snapshot. */
export function resetDemoSnapshotCache(): void {
  snapshotPromise = null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Queries (pure)
// ─────────────────────────────────────────────────────────────────────────────

function findEvent(snapshot: DemoSnapshot, slugOrId: string): HistoricalEvent | undefined {
  return snapshot.events.find((e) => e.slug === slugOrId || e.id === slugOrId);
}

/** Events inside the viewport's year/lat window, plus links whose endpoints are both visible. */
export function demoTiles(snapshot: DemoSnapshot, viewport: CanvasViewport): TileResponse {
  const events = snapshot.events
    .filter(
      (e) =>
        e.year_approx >= viewport.year_min &&
        e.year_approx <= viewport.year_max &&
        e.lat >= viewport.lat_min &&
        e.lat <= viewport.lat_max,
    )
    .sort((a, b) => b.importance_score - a.importance_score);
  const ids = new Set(events.map((e) => e.id));
  const links = snapshot.links.filter((l) => ids.has(l.cause_event_id) && ids.has(l.effect_event_id));
  return { events, links, computed_at: new Date(0).toISOString() };
}

/** All links touching one event. */
export function demoConnections(snapshot: DemoSnapshot, slug: string): CausalityLink[] {
  const ev = findEvent(snapshot, slug);
  if (!ev) return [];
  return snapshot.links.filter((l) => l.cause_event_id === ev.id || l.effect_event_id === ev.id);
}

/** Full event detail (perspectives + connected events), or null if the slug is not in the sample. */
export function demoEventDetail(snapshot: DemoSnapshot, slug: string): EventDetail | null {
  const ev = findEvent(snapshot, slug);
  if (!ev) return null;
  const byId = new Map(snapshot.events.map((e) => [e.id, e]));
  const connected: ConnectedEvent[] = [];
  for (const l of demoConnections(snapshot, ev.slug)) {
    const isCause = l.effect_event_id === ev.id; // the other end caused this event
    const other = byId.get(isCause ? l.cause_event_id : l.effect_event_id);
    if (!other) continue;
    connected.push({
      id: other.id,
      slug: other.slug,
      title: other.title,
      year_approx: other.year_approx,
      connection_type: l.connection_type,
      direction: isCause ? 'cause' : 'effect',
      strength: l.strength,
      description: l.description,
    });
  }
  connected.sort((a, b) => a.year_approx - b.year_approx);
  return {
    ...ev,
    is_bce: ev.year_approx < 0,
    perspectives: snapshot.details[ev.slug]?.perspectives ?? [],
    connected_events: connected,
  };
}

/**
 * Case-insensitive keyword search over title, place, and era label.
 * Title-prefix matches rank first, then by importance.
 */
export function demoSearch(snapshot: DemoSnapshot, q: string, limit = 10): SearchResult[] {
  const needle = q.trim().toLowerCase();
  if (!needle) return [];
  const scored: { e: HistoricalEvent; score: number }[] = [];
  for (const e of snapshot.events) {
    const title = e.title.toLowerCase();
    const haystack = `${title} ${e.geo_modern ?? ''} ${e.geo_era_label ?? ''} ${(e.tags ?? []).join(' ')}`.toLowerCase();
    if (!haystack.includes(needle)) continue;
    const score = (title.startsWith(needle) ? 2 : title.includes(needle) ? 1 : 0) + e.importance_score;
    scored.push({ e, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, Math.max(0, limit)).map(({ e }) => ({
    id: e.id,
    slug: e.slug,
    title: e.title,
    year_approx: e.year_approx,
    geo_modern: e.geo_modern,
    category: e.category,
    importance_score: e.importance_score,
    lat: e.lat,
    lng: e.lng,
  }));
}

/** Category summaries (count + top 3 featured events), sorted by count desc. */
export function demoCategories(snapshot: DemoSnapshot): {
  categories: {
    category: string;
    count: number;
    featured: { id: string; slug: string; title: string; year_approx: number | null; importance_score: number }[];
  }[];
} {
  const groups = new Map<string, HistoricalEvent[]>();
  for (const e of snapshot.events) {
    const list = groups.get(e.category) ?? [];
    list.push(e);
    groups.set(e.category, list);
  }
  const categories = [...groups.entries()]
    .map(([category, list]) => ({
      category,
      count: list.length,
      featured: [...list]
        .sort((a, b) => b.importance_score - a.importance_score)
        .slice(0, 3)
        .map((e) => ({
          id: e.id,
          slug: e.slug,
          title: e.title,
          year_approx: e.year_approx,
          importance_score: e.importance_score,
        })),
    }))
    .sort((a, b) => b.count - a.count || a.category.localeCompare(b.category));
  return { categories };
}
